def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Find the full row or column that acts as the divider.
    line = None
    for r in range(h):
        if all(g[r][c] == 2 for c in range(w)):
            line = ("h", r)
            break
    if line is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                line = ("v", c)
                break
    if line is None:
        return g

    # The most frequent non-divider color is the background.
    from collections import Counter
    counts = Counter(x for row in g for x in row if x != 2)
    bg = counts.most_common(1)[0][0]

    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] != 2 and g[r][c] != bg]
    if not points:
        return g

    rs = [r for r, c in points]
    cs = [c for r, c in points]
    rmin, rmax, cmin, cmax = min(rs), max(rs), min(cs), max(cs)

    if line[0] == "h":
        lr = line[1]
        if rmax < lr:
            dr = lr - 1 - rmax
            trail = rmin + dr - 1
        elif rmin > lr:
            dr = lr + 1 - rmin
            trail = rmax + dr + 1
        else:
            return g
        dc = 0
        if not (0 <= trail < h):
            trail = None
    else:
        lc = line[1]
        if cmax < lc:
            dc = lc - 1 - cmax
            trail = cmin + dc - 1
        elif cmin > lc:
            dc = lc + 1 - cmin
            trail = cmax + dc + 1
        else:
            return g
        dr = 0
        if not (0 <= trail < w):
            trail = None

    # Shift the object toward the divider.
    for r, c in points:
        g[r][c] = bg
    for r, c in points:
        g[r + dr][c + dc] = grid[r][c]

    # Mark the far edge of the shifted object with a full 8-line.
    if trail is not None:
        if line[0] == "h":
            g[trail] = [8] * w
        else:
            for r in range(h):
                g[r][trail] = 8

    return g
